import{_ as a,c as s,o as r,a8 as i}from"./chunks/framework.D4xYyhHC.js";const u=JSON.parse('{"title":"Serverless 无服务器应用程序框架","description":"","frontmatter":{"title":"Serverless 无服务器应用程序框架","urlname":"QyucdjRwao8nIcxsVjicFBwdnmg","date":"2025-04-03 23:37:33","updated":"2025-04-03 23:43:45"},"headers":[],"relativePath":"feishu/docs/编程/框架/QyucdjRwao8nIcxsVjicFBwdnmg.md","filePath":"feishu/docs/编程/框架/QyucdjRwao8nIcxsVjicFBwdnmg.md","lastUpdated":1743995925000}'),l={name:"feishu/docs/编程/框架/QyucdjRwao8nIcxsVjicFBwdnmg.md"};function t(o,e,n,d,h,c){return r(),s("div",null,e[0]||(e[0]=[i('<p><a href="https://www.serverless.com/framework/docs/getting-started" target="_blank" rel="noreferrer">https://www.serverless.com/framework/docs/getting-started</a></p><h2 id="serverless-framework-入门解析" tabindex="-1">Serverless Framework 入门解析 <a class="header-anchor" href="#serverless-framework-入门解析" aria-label="Permalink to &quot;Serverless Framework 入门解析&quot;">​</a></h2><p>Serverless Framework 是一个开源的无服务器应用程序框架，它简化了在各种云服务提供商上开发、部署和管理无服务器应用的过程。</p><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><ol><li><p>跨云平台支持 ：支持 AWS Lambda、Azure Functions、Google Cloud Functions 等多个云平台</p></li><li><p>简化部署 ：通过简单的命令行操作完成复杂的部署流程</p></li><li><p>基础设施即代码 ：使用 YAML 配置文件定义整个应用架构</p></li><li><p>插件生态系统 ：丰富的插件扩展功能</p></li></ol><h2 id="入门步骤" tabindex="-1">入门步骤 <a class="header-anchor" href="#入门步骤" aria-label="Permalink to &quot;入门步骤&quot;">​</a></h2><p>根据文档，入门过程包括以下几个步骤：</p><h3 id="_1-安装-serverless-framework" tabindex="-1">1. 安装 Serverless Framework <a class="header-anchor" href="#_1-安装-serverless-framework" aria-label="Permalink to &quot;1. 安装 Serverless Framework&quot;">​</a></h3><h3 id="_2-创建新项目" tabindex="-1">2. 创建新项目 <a class="header-anchor" href="#_2-创建新项目" aria-label="Permalink to &quot;2. 创建新项目&quot;">​</a></h3><p>这会创建一个基于 AWS Node.js 的项目模板。</p><h3 id="_3-配置项目" tabindex="-1">3. 配置项目 <a class="header-anchor" href="#_3-配置项目" aria-label="Permalink to &quot;3. 配置项目&quot;">​</a></h3><p>编辑 serverless.yml 文件，定义函数、事件触发器和云资源。</p><h3 id="_4-部署应用" tabindex="-1">4. 部署应用 <a class="header-anchor" href="#_4-部署应用" aria-label="Permalink to &quot;4. 部署应用&quot;">​</a></h3><h3 id="_5-调用函数" tabindex="-1">5. 调用函数 <a class="header-anchor" href="#_5-调用函数" aria-label="Permalink to &quot;5. 调用函数&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">serverless</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> invoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --function</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> hello</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><ul><li><p>服务(Service) ：应用的顶级组织单元，通常包含多个函数</p></li><li><p>函数(Function) ：执行特定任务的代码单元</p></li><li><p>事件(Event) ：触发函数执行的事件源</p></li><li><p>资源(Resources) ：应用需要的云资源，如数据库、存储等</p></li><li><p>插件(Plugins) ：扩展框架功能的模块</p></li></ul><p>Serverless Framework 特别适合构建微服务、API、数据处理管道等无需管理服务器的应用场景，可以显著降低运维成本和复杂度。</p>',18)]))}const m=a(l,[["render",t]]);export{u as __pageData,m as default};
